<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($pageTitle,ENT_QUOTES,'UTF-8') ?></title><style>:root{--ink:#342d3b;--muted:#756e7b;--cream:#fffaf4;--lilac:#e9ddfb;--rose:#f6c6d8;--line:#ded5df}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--cream);font-family:Arial,Helvetica,sans-serif}button{font:inherit;cursor:pointer}.shell{width:min(1180px,calc(100% - 40px));margin:auto}.notice{padding:11px;text-align:center;background:var(--ink);color:#fff;font-size:13px}header{padding:22px 0 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:18px}.brand{font:28px Georgia,serif;font-weight:bold;text-decoration:none}.brand span{color:#c581a2}nav{display:flex;gap:22px}nav a{font-size:14px;text-decoration:none;color:var(--ink)}.cart,.back,.add{border:1px solid var(--ink);border-radius:999px;background:transparent;padding:10px 14px}.intro{margin:38px 0;padding:48px clamp(25px,6vw,80px);background:var(--lilac);border-radius:26px}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:bold}.intro h1{margin:16px 0;font:clamp(38px,6vw,66px)/1 Georgia,serif}.intro p{max-width:600px;color:var(--muted);line-height:1.6}.back{display:inline-block;background:var(--ink);color:#fff;text-decoration:none;border:0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:70px}.product{background:#fff;padding:13px;border:1px solid var(--line);border-radius:18px}.product-visual{position:relative;cursor:pointer}.product img{width:100%;height:205px;object-fit:cover;border-radius:12px;display:block}.views{position:absolute;top:8px;left:8px;padding:4px 8px;background:#342d3bbb;color:#fff;border-radius:999px;font-size:11px}.product h2{font:20px Georgia,serif;margin:16px 0 7px}.product p{color:var(--muted);font-size:13px;line-height:1.45;min-height:55px}.row{display:flex;justify-content:space-between;align-items:center;gap:8px}.add{color:#9e5478;border:0;padding:8px 0;font-weight:bold}.empty{grid-column:1/-1;text-align:center;color:var(--muted);padding:40px}footer{border-top:1px solid var(--line);padding:50px 0 26px;display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}footer p,footer a{color:var(--muted);text-decoration:none;line-height:1.8;font-size:14px}footer h3{font:17px Georgia,serif}.copyright{grid-column:1/-1;padding-top:18px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.overlay{display:none;position:fixed;inset:0;z-index:100;background:#342d3bcc;padding:20px;overflow:auto}.overlay.open{display:grid;place-items:center}.modal{width:min(900px,100%);max-height:92vh;overflow:auto;background:var(--cream);border-radius:20px;padding:20px;position:relative}.close{position:absolute;right:15px;top:14px;border:1px solid var(--line);border-radius:50%;width:34px;height:34px;background:#fff}.product-modal{display:grid;grid-template-columns:1.1fr .9fr;gap:25px}.main-image{width:100%;height:360px;object-fit:cover;border-radius:14px;background:var(--lilac)}.thumbs{display:flex;gap:8px;overflow:auto;margin-top:10px}.thumbs button{padding:0;border:2px solid transparent;border-radius:9px;background:none}.thumbs button.active{border-color:var(--ink)}.thumbs img{width:60px;height:60px;object-fit:cover;border-radius:7px;display:block}.details h2{font:32px Georgia,serif;margin:10px 0}.details p{color:var(--muted);line-height:1.55}.price{font-size:20px;font-weight:bold}.modal-add{margin-top:16px;background:var(--ink);color:#fff;border:0;border-radius:999px;padding:12px 17px}.reviews{grid-column:1/-1;border-top:1px solid var(--line);padding-top:20px}.stars{color:#bd6f92;letter-spacing:2px}.review{border-top:1px solid var(--line);padding:12px 0}.review p{margin:6px 0;color:var(--muted)}.review-form{display:grid;gap:9px;margin-top:15px}.review-form input,.review-form textarea,.review-form select{padding:10px;border:1px solid var(--line);border-radius:8px;font:inherit}.review-form textarea{min-height:80px}.review-form button{justify-self:start;border:0;background:var(--ink);color:#fff;border-radius:999px;padding:10px 15px}.cart-modal{width:min(580px,100%)}.cart-row{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}.cart-row small{display:block;color:var(--muted)}.quantity{display:flex;align-items:center;gap:7px}.quantity button{width:27px;height:27px;border:1px solid var(--line);border-radius:50%;background:#fff}.remove{border:0;background:none;color:#9e5478}.total{display:flex;justify-content:space-between;font-size:20px;font-weight:bold;padding-top:18px}@media(max-width:760px){.shell{width:min(100% - 28px,600px)}header{flex-wrap:wrap}nav{order:3;width:100%;justify-content:space-between;gap:8px}.grid{grid-template-columns:repeat(2,1fr);gap:10px}.product{padding:10px}.product img{height:155px}.product-modal{grid-template-columns:1fr}.main-image{height:300px}footer{grid-template-columns:1fr 1fr}footer>:first-child{grid-column:1/-1}}@media(max-width:420px){.grid{grid-template-columns:1fr}.cart-row{grid-template-columns:1fr auto}}</style></head><body><div class="notice">Entrega local el mismo día · Haz que el detalle llegue hoy</div><main class="shell"><header><a class="brand" href="index.php">Jenlu <span>Sv</span></a><nav><a href="index.php">Inicio</a><a href="index.php#regalos">Regalos</a><a href="index.php#historia">Nuestra idea</a><a href="#contacto">Contacto</a></nav><button class="cart" id="cart">Bolsa · 0</button></header><?php if($categoryName): ?><section class="intro"><div class="eyebrow">Colección Jenlu Sv</div><h1><?= htmlspecialchars($categoryName,ENT_QUOTES,'UTF-8') ?></h1><p>Detalles preparados para celebrar y sorprender. Toca un producto para ver sus fotos, información y opiniones.</p><a class="back" href="index.php#regalos">Ver todas las categorías</a></section><section class="grid" id="grid"></section><?php else: ?><section class="intro"><h1>Categoría no encontrada</h1><a class="back" href="index.php#regalos">Volver a regalos</a></section><?php endif; ?><footer id="contacto"><div><a href="index.php" class="brand">Jenlu <span>Sv</span></a><p>Regalos para ella, para él y para cada fecha especial, a tu manera.</p></div><div><h3>Explora</h3><p><a href="index.php#regalos">Regalos</a><br><a href="index.php#historia">Nuestra idea</a><br><a href="#contacto">Entregas</a></p></div><div><h3>Contacto</h3><p>hola@jenlusv.example<br>+503 0000 0000<br>San Salvador</p></div><div class="copyright">© 2026 Jenlu Sv. Todos los derechos reservados.</div></footer></main><?php if($categoryName): ?><div class="overlay" id="productOverlay"><section class="modal"><button class="close" data-close="productOverlay">✕</button><div class="product-modal"><div><img class="main-image" id="modalImage" alt=""><div class="thumbs" id="thumbs"></div></div><div class="details"><div class="eyebrow">Detalle del producto</div><h2 id="modalName"></h2><p id="modalDescription"></p><div class="price" id="modalPrice"></div><button class="modal-add" id="modalAdd">Añadir a la bolsa</button></div><section class="reviews"><h3>Opiniones</h3><div id="reviews"></div><form class="review-form" id="reviewForm"><input id="reviewName" maxlength="80" placeholder="Tu nombre" required><select id="reviewRating" required><option value="">Calificación</option><option value="5">★★★★★ · 5 estrellas</option><option value="4">★★★★☆ · 4 estrellas</option><option value="3">★★★☆☆ · 3 estrellas</option><option value="2">★★☆☆☆ · 2 estrellas</option><option value="1">★☆☆☆☆ · 1 estrella</option></select><textarea id="reviewComment" maxlength="500" placeholder="Cuéntanos qué te pareció" required></textarea><button>Publicar reseña</button></form></section></div></section></div><div class="overlay" id="cartOverlay"><section class="modal cart-modal"><button class="close" data-close="cartOverlay">✕</button><h2>Tu bolsa</h2><div id="cartItems"></div><div class="total"><span>Total</span><span id="cartTotal">$0</span></div></section></div><script>const category=<?= json_encode($slug,JSON_UNESCAPED_UNICODE) ?>,grid=document.querySelector('#grid'),cart=document.querySelector('#cart'),money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v),escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));let products=[],active=null;async function api(url,options){const r=await fetch(url,options);const data=await r.json();if(!r.ok)throw new Error(data.error||'Ocurrió un error');return data}async function loadCart(){const data=await api('api.php?action=cart');cart.textContent=`Bolsa · ${data.count}`;return data}async function renderCart(){const data=await loadCart(),el=document.querySelector('#cartItems');el.innerHTML=data.items.length?data.items.map(i=>`<div class="cart-row"><div><strong>${escapeHtml(i.name)}</strong><small>${money(i.price)} c/u</small></div><div class="quantity"><button data-change="${i.id}" data-q="${i.quantity-1}">−</button><span>${i.quantity}</span><button data-change="${i.id}" data-q="${i.quantity+1}">+</button></div><button class="remove" data-remove="${i.id}">Quitar</button></div>`).join(''):'<p>Tu bolsa está vacía.</p>';document.querySelector('#cartTotal').textContent=money(data.total);el.querySelectorAll('[data-change]').forEach(b=>b.onclick=async()=>{await api('api.php?action=cart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'update',productId:+b.dataset.change,quantity:+b.dataset.q})});renderCart()});el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{await api('api.php?action=cart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation:'remove',productId:+b.dataset.remove})});renderCart()})}function stars(r){return '★'.repeat(r)+'☆'.repeat(5-r)}async function loadReviews(){const data=await api(`api.php?action=reviews&productId=${active.id}`),el=document.querySelector('#reviews');el.innerHTML=data.reviews.length?data.reviews.map(r=>`<article class="review"><strong>${escapeHtml(r.customer_name)}</strong> <span class="stars">${stars(+r.rating)}</span><p>${escapeHtml(r.comment)}</p></article>`).join(''):'<p>Aún no hay reseñas. ¡Sé la primera persona en opinar!</p>'}function showImage(i){document.querySelector('#modalImage').src=active.images[i].url;document.querySelector('#modalImage').alt=active.name;document.querySelectorAll('#thumbs button').forEach((b,n)=>b.classList.toggle('active',n===i))}async function openProduct(product){active=product;document.querySelector('#modalName').textContent=product.name;document.querySelector('#modalDescription').textContent=product.description;document.querySelector('#modalPrice').textContent=money(product.price);document.querySelector('#thumbs').innerHTML=product.images.map((im,i)=>`<button data-i="${i}"><img src="${escapeHtml(im.url)}" alt="${escapeHtml(im.label||'Vista')}"></button>`).join('');document.querySelectorAll('#thumbs button').forEach(b=>b.onclick=()=>showImage(+b.dataset.i));showImage(0);document.querySelector('#productOverlay').classList.add('open');await loadReviews()}async function add(id){await api('api.php?action=cart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productId:id})});loadCart()}async function loadProducts(){try{const data=await api(`api.php?action=products&category=${encodeURIComponent(category)}`);products=data.products;grid.innerHTML=products.length?products.map((p,i)=>`<article class="product"><div class="product-visual" data-product="${i}"><img src="${escapeHtml(p.images?.[0]?.url||'')}" alt="${escapeHtml(p.name)}">${p.images.length>1?`<span class="views">${p.images.length} vistas</span>`:''}</div><h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.description)}</p><div class="row"><span>${money(p.price)}</span><button class="add" data-add="${p.id}">Añadir</button></div></article>`).join(''):'<p class="empty">Pronto tendremos productos en esta colección.</p>';grid.querySelectorAll('[data-product]').forEach(x=>x.onclick=()=>openProduct(products[+x.dataset.product]));grid.querySelectorAll('[data-add]').forEach(x=>x.onclick=e=>{e.stopPropagation();add(+x.dataset.add)})}catch{grid.innerHTML='<p class="empty">No se pudieron cargar los productos.</p>'}}document.querySelector('#modalAdd').onclick=()=>add(active.id);document.querySelector('#cart').onclick=()=>{document.querySelector('#cartOverlay').classList.add('open');renderCart()};document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>document.querySelector('#'+x.dataset.close).classList.remove('open'));document.querySelectorAll('.overlay').forEach(x=>x.addEventListener('click',e=>{if(e.target===x)x.classList.remove('open')}));document.querySelector('#reviewForm').onsubmit=async e=>{e.preventDefault();try{await api(`api.php?action=reviews&productId=${active.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.querySelector('#reviewName').value,rating:+document.querySelector('#reviewRating').value,comment:document.querySelector('#reviewComment').value})});e.target.reset();loadReviews()}catch(err){alert(err.message)}};loadProducts();loadCart();</script><?php endif; ?></body></html>
